import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlPopoverComponent } from '@domg-wc/components/block';

// vl-popover registreert vl-popover-action-list en vl-popover-action zelf.
registerWebComponents([VlPopoverComponent, VlButtonComponent]);

// Markeer de aangeklikte actie met het attribuut selected en haal het weg bij de andere acties. action is vrije data
// bij de actie, bv. om te bepalen wat er moet gebeuren.
document.querySelector('vl-popover-action-list').addEventListener('click', (event) => {
    const actionElement = event.target.closest('vl-popover-action');
    if (!actionElement) return;
    console.log(actionElement.action);
    actionElement.parentElement.querySelectorAll('vl-popover-action').forEach((item) => {
        if (item !== actionElement) item.removeAttribute('selected');
    });
    actionElement.setAttribute('selected', '');
});

